WoWFA_Data[394048] = "ورود به Eclipse، شانس Critical Strike شما با اسپل‌های Arcane یا Nature را 20% افزایش می‌دهد؛ این مقدار هر 1 ثانیه 2% کاهش می‌یابد."
WoWFA_Data[394065] = "Moonfire و Sunfire شما شانس دارند یک Faerie Dragon را برای 30 ثانیه احضار کنند تا در نبرد به شما کمک کند."
WoWFA_Data[394094] = "هر یک‌درمیان یک Eclipse، یک Fury of Elune با اثربخشی 25% می‌سازد که برای 8 ثانیه هدف فعلی شما را دنبال می‌کند."
WoWFA_Data[394121] = "آسیب New Moon، Half Moon و Full Moon به‌اندازهٔ 25% افزایش می‌یابد. Full Moon پیش از بازگشت به New Moon، یک بار دیگر تبدیل به Full Moon می‌شود.\n\nآسیب Fury of Elune به‌اندازهٔ 50% افزایش می‌یابد و کول‌داون آن به‌اندازهٔ 15 ثانیه کاهش می‌یابد."
WoWFA_Data[395022] = "Celestial bodies align, maintaining both Eclipses and granting 10% haste for 15 ثانیه."
WoWFA_Data[400059] = "Moonfire و Sunfire شما 20% پرتواترتر آسیب وارد می‌کنند و نرخ فرود Shooting Stars را نیز افزایش می‌دهند."
WoWFA_Data[400129] = "کست کردن Regrowth، سرعت حرکت و شفای دریافتی شما را برای 6 ثانیه به‌اندازهٔ 8% افزایش می‌دهد."
WoWFA_Data[400140] = "کول‌داون Typhoon را به‌اندازهٔ 5 ثانیه کاهش می‌دهد."
WoWFA_Data[400142] = "شعاع Typhoon را به‌اندازهٔ 20% و برد آن را 5 یارد افزایش می‌دهد."
WoWFA_En[400254] = "Strike with the might of Ursoc, dealing $s1 Physical damage to your target and $s2 to all other enemies in front of you. Damage reduced beyond $s3 targets."
WoWFA_Data[400254] = "با قدرت Ursoc ضربه می‌زنید؛ $s1 آسیب Physical به هدف و $s2 آسیب به تمام دشمنان دیگر جلوی شما وارد می‌کنید. آسیب پس از 5 هدف کاهش می‌یابد."
WoWFA_Data[400278] = "توانایی‌های نزدیک آسیب‌مستقیم شما علیه دشمنان تحت Moonfire، باعث می‌شود آن‌ها 20% آسیب Arcane اضافی از سوختن دریافت کنند."
WoWFA_Data[400320] = "اثرات آسیب در طول زمان شما، آسیب خود را در زمانی 20% کوتاه‌تر وارد می‌کنند و اثرات شفا در طول زمان شما، شفای خود را در زمانی 15% کوتاه‌تر وارد می‌کنند."
WoWFA_Data[400533] = "Grove Guardianها، Efflorescence و سایر احضارشده‌های شما 30% بیشتر شفا می‌دهند."
WoWFA_Data[403521] = "شانس فعال‌سازی Clearcasting توسط Omen of Clarity را به 5% می‌رساند و Clearcasting می‌تواند 1 بار دیگر استک شود."
WoWFA_Data[404521] = "شفای در طول زمان Regrowth به‌اندازهٔ 100% افزایش می‌یابد و روی هدف Lifebloom شما نیز اعمال می‌شود."
WoWFA_Data[406890] = "شانس Critical Strike Wrath و Starfire شما به‌اندازهٔ 10% افزایش می‌یابد و این دو، 2 Astral Power اضافی تولید می‌کنند."
WoWFA_Data[421432] = "وقتی انرژی اضافی روی Ferocious Bite مصرف می‌کنید، آسیب اضافی به‌اندازهٔ 60% افزایش می‌یابد."
WoWFA_En[424058] = "$?a137010[$@spellicon204066 $@spellname204066\nLunar Beam now causes you to leech life equal to $425217s1% of all damage dealt to enemies within the beam.\n\n$@spellicon202770 $@spellname202770\nFury of Elune now ends with a flash of energy, blasting nearby enemies for $428682s1 Astral damage.]\n\n[$@spellicon202770 $@spellname202770\nFury of Elune now ends with a flash of energy, blasting nearby enemies for $428682s1 Astral damage.\n\n$@spellicon274283 $@spellname274283\n$@spelldesc424588]"
WoWFA_Data[424058] = "$?a137010[ Lunar Beam\nاسپل Lunar Beam اکنون به شما شفایی برابر با 12% از تمام آسیب واردشده به دشمنان داخل پرتو می‌دهد.\n\n Fury of Elune\nاسپل Fury of Elune اکنون با فورانی از انرژی تمام می‌شود و به دشمنان نزدیک $428682s1 آسیب Astral وارد می‌کند.]\n\n[ Fury of Elune\nاسپل Fury of Elune اکنون با فورانی از انرژی تمام می‌شود و به دشمنان نزدیک $428682s1 آسیب Astral وارد می‌کند.\n\n Full Moon\n$?a424113[New Moon and Half Moon call down 1 Minor $LMoon:Moons; and ][]Full Moon calls down 2 Minor $LMoon:Moons; that $Ldeals:deal; 2 Astral damage and generate 3 Astral Power.]"
WoWFA_En[424113] = "Further increases the power of Boundless Moonlight.\n\n$?a137010[$@spellicon204066 $@spellname204066\nLunar Beam increases Mastery by an additional ${$s5*$mas}%, deals $s6% increased damage, and lasts ${$s3/1000} sec longer.\n\n$@spellicon202770 $@spellname202770\nThe flash of energy now generates  ${$428682s3/10} Rage and its damage is increased by $s1%.][$@spellicon202770 $@spellname202770\nThe flash of energy now generates ${$428682s2/10} Astral Power and its damage is increased by $s1%.\n\n$@spellicon274283 $@spellname274283\nNew Moon and Half Moon now also call down $s2 Minor $LMoon:Moons;.]"
WoWFA_Data[424113] = "قدرت Boundless Moonlight را باز هم بیشتر افزایش می‌دهد.\n\n$?a137010[ Lunar Beam\nLunar Beam، Mastery را ${$s5*$mas}% دیگر افزایش می‌دهد، 30% آسیب بیشتری وارد می‌کند و 3 ثانیه بیشتر دوام می‌آورد.\n\n Fury of Elune\nفوران انرژی اکنون  6 خشم تولید می‌کند و آسیب آن 50% افزایش می‌یابد.][ Fury of Elune\nفوران انرژی اکنون 6 Astral Power تولید می‌کند و آسیب آن 50% افزایش می‌یابد.\n\n Full Moon\nNew Moon و Half Moon اکنون همچنین 1 ماه کوچک فرامی‌خوانند.]"
WoWFA_Data[426702] = "اثرات آسیب در طول زمان شما 25% سریع‌تر آسیب وارد می‌کنند و اثرات شفای در طول زمان شما 5% سریع‌تر شفا می‌دهند."
WoWFA_En[426784] = "When you cast Starsurge, Rake, Shred, or Frenzied Regeneration you gain Call of the Elder Druid for $s2 sec, once every $338643d.\n\n$@spellicon319454 $@spellname319454\n$@spelldesc319454"
WoWFA_Data[426784] = "وقتی Starsurge، Rake، Shred یا Frenzied Regeneration کست می‌کنید، هر 1 دقیقه یک بار، برای 15 ثانیه Call of the Elder Druid می‌گیرید.\n\n Call of the Elder Druid\nAbilities not associated with your specialization are substantially empowered for 45 ثانیه.$?!s137013[\n\n|cFFFFFFFFBalance:|r Cast time of Balance spells reduced by 30% and damage increased by 20%.][]$?!s137011[\n\n|cFFFFFFFFFeral:|r Gain 1 Combo Point every 2 sec while in Cat Form and Physical damage increased by 20%.][]$?!s137010[\n\n|cFFFFFFFFGuardian:|r Bear Form gives an additional 20% Stamina, multiple uses of Ironfur may overlap, and Frenzied Regeneration has 2 charges.][]$?!s137012[\n\n|cFFFFFFFFRestoration:|r Healing increased by 30%, and mana costs reduced by 50%.][]"
WoWFA_En[428544] = "Your $?a137013[Force of Nature treants][Grove Guardians] cast Moonfire on nearby targets about once every $s1 sec."
WoWFA_Data[428544] = "$?a137013[Treant‌های Force of Nature شما][Grove Guardianهای شما] تقریباً هر 6 ثانیه یک بار روی اهداف نزدیک Moonfire کست می‌کنند."
WoWFA_En[428655] = "Moonfire damage has a chance to call down a Fury of Elune to follow your target for ${$s2/1000} sec.\n\n$@spellicon202770 $@spellname202770\nCalls down a beam of pure celestial energy, dealing $<dmg> Astral damage over ${$s2/1000} sec within its area.\n\n|cFFFFFFFFGenerates $?a137010[${$202770m4/$202770t4*$s2/10000} Rage][${$202770m3/$202770t3*$s2/10000} Astral Power] over its duration.|r"
WoWFA_Data[428655] = "آسیب Moonfire شانس دارد یک Fury of Elune فرابخواند که برای 3 ثانیه هدف شما را دنبال می‌کند.\n\n Fury of Elune\nپرتوهایی از انرژی آسمانی خالص فرود می‌آورد که در محدودهٔ خود طی 3 ثانیه، $<dmg> آسیب Astral وارد می‌کند.\n\n|cFFFFFFFFدر طول مدت خود، $?a137010[18 خشم][15 Astral Power] تولید می‌کند.|r"
WoWFA_En[428731] = "$?a137013[Each of your Force of Nature treants increases damage your spells deal by $428735s1% while active.][Each of your Grove Guardians increases your healing done by $428737s1% while active.]"
WoWFA_Data[428731] = "$?a137013[هر یک از Treantهای Force of Nature شما در طول فعال‌بودن، آسیب اسپل‌های شما را 4% افزایش می‌دهد.][هر یک از Grove Guardianهای شما در طول فعال‌بودن، شفای واردشدهٔ شما را 5% افزایش می‌دهد.]"
WoWFA_En[428859] = "$?a137013[Your Force of Nature treants no longer taunt and deal $449001s1% increased melee damage.][Your Grove Guardians increase the healing of your Rejuvenation, Efflorescence, and Lifebloom by $428866s1% while active.]"
WoWFA_Data[428859] = "$?a137013[Treantهای Force of Nature شما دیگر تانت نمی‌کنند و 300% آسیب نزدیک بیشتری وارد می‌کنند.][Grove Guardianهای شما در طول فعال‌بودن، شفای Rejuvenation، Efflorescence و Lifebloom شما را 10% افزایش می‌دهند.]"
WoWFA_En[428937] = "$?a137013[Force of Nature cooldown reduced by ${$s1/-1000} sec.][Swiftmend and Wild Growth cooldowns reduced by ${$s2/-1000} sec.]"
WoWFA_Data[428937] = "$?a137013[کول‌داون Force of Nature به‌اندازهٔ 15 ثانیه کاهش می‌یابد.][کول‌داون Swiftmend و Wild Growth به‌اندازهٔ 1 ثانیه کاهش می‌یابد.]"
WoWFA_En[429215] = "$?a137013[Force of Nature Treants last ${$s2/1000} sec longer.][Your Grove Guardians' healing is increased by $s1%.]"
WoWFA_Data[429215] = "$?a137013[Treantهای Force of Nature 4 ثانیه بیشتر دوام می‌آورند.][شفای Grove Guardianهای شما به‌اندازهٔ 30% افزایش می‌یابد.]"
WoWFA_En[429227] = "$?c1[Your Force of Nature treants have $s1% increased health.][Grove Guardians last $s2% longer.]"
WoWFA_Data[429227] = "$?c1[Treantهای Force of Nature شما 100% سلامتی بیشتری دارند.][Grove Guardianها 20% بیشتر دوام می‌آورند.]"
WoWFA_En[429399] = "Your maximum mana is increased by $s2%$?a137013[ and your maximum Astral Power is increased by ${$s1/10}][]."
WoWFA_Data[429399] = "حداکثر Mana شما به‌اندازهٔ 5% افزایش می‌یابد$?a137013[ و حداکثر Astral Power شما 20 افزایش می‌یابد][]."
WoWFA_En[429402] = "Wrath and Starfire damage increased by $s1%. \n\nRegrowth$?a137013[ and Wild Growth][, Wild Growth, and Swiftmend] healing increased by $s2%."
WoWFA_Data[429402] = "آسیب Wrath و Starfire به‌اندازهٔ 10% افزایش می‌یابد. \n\nشفای Regrowth$?a137013[ و Wild Growth][، Wild Growth و Swiftmend] به‌اندازهٔ 9% افزایش می‌یابد."
WoWFA_En[429420] = "$?c1[Orbital Strike damage increased by $s3%, and damage of Stellar Flares it applies increased by $s2%.\n\nWhirling Stars increases the haste you gain during ][]$?c1&s394013[Incarnation: Chosen of Elune]?c1[Celestial Alignment][]$?c1[ by an additional $s4%.][Reforestation grants Tree of Life for $s5 additional sec.]"
WoWFA_Data[429420] = "$?c1[آسیب Orbital Strike به‌اندازهٔ 30% و آسیب Stellar Flareهای اعمال‌شدهٔ آن به‌اندازهٔ 30% افزایش می‌یابد.\n\nWhirling Stars، Haste‌ای که در طول ][]$?c1&s394013[Incarnation: Chosen of Elune]?c1[Celestial Alignment][]$?c1[ می‌گیرید را 6% دیگر افزایش می‌دهد.][Reforestation به‌مدت 6 ثانیه بیشتر Tree of Life می‌دهد.]"
WoWFA_En[429433] = "Every $s1 Regrowths you cast makes your next Wrath, Starfire, or Entangling Roots instant and increases damage it deals by $429474s2%.\n\nEvery $s1 Starsurges $?a137013[or Starfalls ][]you cast makes your next Regrowth or Entangling roots instant."
WoWFA_Data[429433] = "هر 5 بار کست Regrowth، Wrath، Starfire یا Entangling Roots بعدی شما را کست فوری کرده و آسیب آن را 100% افزایش می‌دهد.\n\nهر 5 بار کست Starsurge $?a137013[یا Starfall ][]، Regrowth یا Entangling Roots بعدی شما را کست فوری می‌کند."
WoWFA_En[429520] = "$?a137013[Moonfire and Starfire generate ${$s1/10} additional Astral Power.][Free automatic Moonfires from Galactic Guardian generate ${$430581s1/10} Rage.]"
WoWFA_Data[429520] = "$?a137013[Moonfire و Starfire 2 Astral Power اضافی تولید می‌کنند.][Moonfireهای خودکار و رایگان Galactic Guardian، 5 خشم تولید می‌کنند.]"
WoWFA_En[429523] = "$?a137013[Starfire deals $s1% increased damage to its primary target.\n\nWrath no longer changes your Eclipse ability's mode to Solar Eclipse.][Thrash now deals Arcane damage and its damage is increased by $s2%.]"
WoWFA_Data[429523] = "$?a137013[آسیب Starfire به هدف اصلی‌اش 120% افزایش می‌یابد.\n\nWrath دیگر حالت اسپل Eclipse شما را به Eclipse خورشیدی تغییر نمی‌دهد.][Thrash اکنون آسیب Arcane وارد می‌کند و آسیب آن 12% افزایش می‌یابد.]"
WoWFA_En[429530] = "Moonfire deals $s1% increased damage.$?a137010[\n\nRed Moon deals $s3% increased damage.][]"
WoWFA_Data[429530] = "آسیب Moonfire به‌اندازهٔ 20% افزایش می‌یابد.$?a137010[\n\nآسیب Red Moon به‌اندازهٔ 30% افزایش می‌یابد.][]"
WoWFA_En[429532] = "Enemies damaged by $?a137013[Full Moon or Fury of Elune][Lunar Beam or Fury of Elune] take $430589s1% increased damage from you for $430589d."
WoWFA_Data[429532] = "دشمنانی که از $?a137013[Full Moon یا Fury of Elune][Lunar Beam یا Fury of Elune] آسیب می‌گیرند، برای 6 ثانیه، 6% آسیب بیشتری از شما دریافت می‌کنند."
WoWFA_Data[429533] = "Bear Form و Moonkin Form، آسیب Arcane دریافتی را 6% و انواع دیگر آسیب جادویی دریافتی را 3% کاهش می‌دهند."
WoWFA_En[429536] = "$?a137013[Incarnation: Chosen of Elune][Incarnation: Guardian of Ursoc] increases Arcane damage from spells and abilities by $102560s6% while active.\n\nIncreases the duration and number of spells cast by Convoke the Spirits by $s1%."
WoWFA_Data[429536] = "$?a137013[اسپل Incarnation: Chosen of Elune][اسپل Incarnation: Guardian of Ursoc] در طول فعال‌بودن، آسیب Arcane اسپل‌ها و توانایی‌های شما را 10% افزایش می‌دهد.\n\nمدت و تعداد اسپل‌های کست‌شدهٔ Convoke the Spirits را 25% افزایش می‌دهد."
WoWFA_Data[429538] = "دشمنان تحت Moonfire به‌اندازهٔ 20% کند می‌شوند."
WoWFA_En[429539] = "$?a137013[Your Arcane abilities reduce the cooldown of Fury of Elune by ${$s1/-1000}.1 sec and the cooldown of New Moon, Half Moon, and Full Moon by ${$s2/-1000}.1 sec.][Lunar Beam's cooldown is reduced by ${-$s3/1000} sec.]\n"
WoWFA_Data[429539] = "$?a137013[توانایی‌های Arcane شما کول‌داون Fury of Elune را 1.5 ثانیه و کول‌داون New Moon، Half Moon و Full Moon را 1 ثانیه کاهش می‌دهند.][کول‌داون Lunar Beam به‌اندازهٔ 20 ثانیه کاهش می‌یابد.]"
WoWFA_Data[429540] = "تمام آسیب Arcane اسپل‌ها و توانایی‌های شما به‌اندازهٔ 3% افزایش می‌یابد."
WoWFA_En[429668] = "$?a137013[Increases the damage of Fury of Elune by $s1% and the damage of Full Moon by $s2%.][Increases the damage of Lunar Beam by $s3% and Fury of Elune by $s1%.]"
WoWFA_Data[429668] = "$?a137013[آسیب Fury of Elune را 15% و آسیب Full Moon را 25% افزایش می‌دهد.][آسیب Lunar Beam را 30% و Fury of Elune را 15% افزایش می‌دهد.]"
WoWFA_Data[433748] = "Regrowth شما از شما محافظت می‌کند و وقتی Regrowth روی شما باشد، آسیب دریافتی را 8% کاهش می‌دهد."
WoWFA_En[433831] = "$?a137013[Force of Nature grants $s1 charges of Dream Burst, causing your next Wrath or Starfire to explode on the target, dealing ${$433850s1*(1+$393014s3/100)} Nature damage to nearby enemies. Damage reduced above $433850s2 targets.][When Grove Guardians are summoned, they grow Dream Petals on your target, healing up to $s2 nearby allies for $434141s1.]"
WoWFA_Data[433831] = "$?a137013[Force of Nature، 3 شارژ Dream Burst می‌دهد که باعث می‌شود Wrath یا Starfire بعدی شما روی هدف منفجر شود و به دشمنان نزدیک ${$433850s1*(1+$393014s3/100)} آسیب Nature وارد کند. آسیب پس از 5 هدف کاهش می‌یابد.][وقتی Grove Guardianها احضار می‌شوند، روی هدف شما Dream Petal می‌رویانند که تا 3 متحد نزدیک را به‌اندازهٔ $434141s1 شفا می‌دهد.]"
WoWFA_En[434220] = "$?a137013[Force of Nature grants an additional stack of Dream Burst.][Dream Surge heals $s2 additional $Lally:allies;.]"
WoWFA_Data[434220] = "$?a137013[Force of Nature یک استک اضافی Dream Burst می‌دهد.][Dream Surge روی 1 متحد دیگر نیز شفا می‌دهد.]"
WoWFA_En[434249] = "Time elapsed while your major abilities are available to be used or at maximum charges is subtracted from that ability's cooldown after the next time you use it, up to $s1 seconds.\n\nAffects $?a137012[Nature's Swiftness, Incarnation: Tree of Life,][Force of Nature,] $?a137012[]?a394013[Incarnation: Chosen of Elune, ][Celestial Alignment, ]and Convoke the Spirits."
WoWFA_Data[434249] = "مدتی که توانایی‌های اصلی شما آمادهٔ استفاده هستند یا شارژ کامل دارند، پس از استفادهٔ بعدی از آن توانایی از کول‌داون آن کم می‌شود؛ تا سقف 15 ثانیه.\n\nروی $?a137012[Nature's Swiftness، Incarnation: Tree of Life،][Force of Nature،] $?a137012[]?a394013[Incarnation: Chosen of Elune، ][Celestial Alignment، ]و Convoke the Spirits اثر می‌گذارد."
WoWFA_En[439528] = "Rip and Rake damage has a chance to cause Bloodseeker Vines to grow on the victim, dealing $439531o1 Bleed damage over $439531d.\n\n$?a137011[Wild Growth and Regrowth][Wild Growth, Regrowth, and Efflorescence] healing has a chance to cause Symbiotic Blooms to grow on the target, healing for $439530o1 over $439530d.\n\nMultiple instances of these can overlap."
WoWFA_Data[439528] = "آسیب Rip و Rake شانس دارد روی قربانی Bloodseeker Vine برویاند که طی 6 ثانیه، $439531o1 آسیب Bleed وارد می‌کند.\n\nشفای $?a137011[Wild Growth و Regrowth][Wild Growth، Regrowth و Efflorescence] شانس دارد روی هدف Symbiotic Bloom برویاند که طی 6 ثانیه، $439530o1 شفا می‌دهد.\n\nچند نمونه از این‌ها می‌توانند هم‌زمان وجود داشته باشند."
WoWFA_Data[439868] = "در حالت Cat Form، آسیب و شفا به‌اندازهٔ 3% افزایش می‌یابد.\n\nآسیب Moonfire و Sunfire به‌اندازهٔ 10% افزایش می‌یابد."
WoWFA_Data[439880] = "Bloodseeker Vineها و Symbiotic Bloomها 2 ثانیه بیشتر دوام می‌آورند.\n\nوقتی هدفی تحت Bloodseeker Vine می‌میرد، تا پایان مدت باقی‌مانده به هدف معتبر دیگری در نزدیکی می‌جهد."
WoWFA_Data[439882] = "هر Bloodseeker Vine فعال، آسیب توانایی‌های شما را 2% افزایش می‌دهد.\n\nهر Symbiotic Bloom فعال، شفای اسپل‌های شما را 2% افزایش می‌دهد."
WoWFA_En[439890] = "$?a137011[Tiger's Fury and attacking from Prowl increase][Attacking from Prowl increases] the chance for Shred, Rake, and $?s202028[Brutal Slash][Swipe] to critically strike by $439891s1% for $439891d.\n\nYour periodic heals have a $s1% increased chance to critically heal."
WoWFA_Data[439890] = "$?a137011[Tiger's Fury و حمله از حالت Prowl،][حمله از حالت Prowl،] شانس Critical Strike خوردن Shred، Rake و $?s202028[Brutal Slash][Swipe] را برای 6 ثانیه به‌اندازهٔ 8% افزایش می‌دهد.\n\nشفاهای دوره‌ای شما 4% شانس بیشتری برای شفای Critical Strike دارند."
WoWFA_Data[439895] = "دشمنانی که به Ursol's Vortex کشیده می‌شوند، برای 3 ثانیه در جای خود ریشه می‌شوند. آسیب ممکن است اثر را لغو کند."
WoWFA_En[439901] = "During Barkskin your movement speed is increased by $s1% and every second flowers grow beneath your feet that heal up to $439902s2 nearby injured allies for $439902s1."
WoWFA_Data[439901] = "در طول Barkskin، سرعت حرکت شما 10% افزایش می‌یابد و هر ثانیه گل‌هایی زیر پای شما می‌روید که تا 3 متحد آسیب‌دیدهٔ نزدیک را به‌اندازهٔ $439902s1 شفا می‌دهد."
WoWFA_En[439926] = "Rip and Ferocious Bite damage increased by $s1%.\n\nRejuvenation$?a137012[, Efflorescence, and Lifebloom][] healing increased by $s3%."
WoWFA_Data[439926] = "آسیب Rip و Ferocious Bite به‌اندازهٔ 5% افزایش می‌یابد.\n\nشفای Rejuvenation$?a137012[، Efflorescence و Lifebloom][] به‌اندازهٔ 10% افزایش می‌یابد."
WoWFA_Data[439929] = "شفای دریافتی شما به‌اندازهٔ 4% افزایش می‌یابد."
WoWFA_Data[440116] = "شفای Regrowth شما روی خودتان به‌اندازهٔ 35% افزایش می‌یابد."
WoWFA_Data[440117] = "وقتی Bloodseeker Vine یا Symbiotic Bloom می‌روید، 30% شانس دارد که فوراً نوع دیگری از همان نوع روی هدف معتبر دیگری در نزدیکی بروید."
WoWFA_En[440118] = "$?a137011[When you gain or lose Tiger's Fury, your next single-target melee ability causes a Bloodseeker Vine to grow on the target for ${$s1/1000} sec.][Casting Swiftmend or Wild Growth causes a Symbiotic Bloom to grow on a target for ${$s2/1000} sec.]"
WoWFA_Data[440118] = "$?a137011[وقتی Tiger's Fury می‌گیرید یا از دست می‌دهید، توانایی نزدیک تک‌هدف بعدی شما باعث می‌شود برای 4 ثانیه یک Bloodseeker Vine روی هدف بروید.][کست کردن Swiftmend یا Wild Growth باعث می‌شود برای 6 ثانیه یک Symbiotic Bloom روی هدفی بروید.]"
WoWFA_Data[440119] = "Bloodseeker Vineها آسیبی که توانایی‌های شما به دشمنان تحت اثر وارد می‌کند را 4% افزایش می‌دهند.\n\nSymbiotic Bloomها شفایی که اسپل‌های شما به اهداف تحت اثر می‌دهد را 20% افزایش می‌دهند."
WoWFA_En[440120] = "When Bloodseeker Vines expire or you use Ferocious Bite on their target they explode in thorns, dealing $440122s1 physical damage to nearby enemies. Damage reduced above 5 targets.\n\nWhen Symbiotic Blooms expire or you cast Rejuvenation on their target flowers grow around their target, healing them and up to $440121s2 nearby allies for $440121s1."
WoWFA_Data[440120] = "وقتی Bloodseeker Vineها تمام می‌شوند یا روی هدفشان Ferocious Bite می‌زنید، به خارهایی منفجر می‌شوند و به دشمنان نزدیک $440122s1 آسیب Physical وارد می‌کنند. آسیب پس از 5 هدف کاهش می‌یابد.\n\nوقتی Symbiotic Bloomها تمام می‌شوند یا روی هدفشان Rejuvenation کست می‌کنید، گل‌هایی دور هدفشان می‌روید که به او و تا 3 متحد نزدیک، $440121s1 شفا می‌دهد."
WoWFA_En[441583] = "Your auto-attacks have a chance to make your next $?a137010[Maul][Ferocious Bite] become Ravage.\n\n$?a137010[$@spellicon441605|cFFFFFFFF$@spellname441605|r\n$@spelldesc441605]$?a137011[$@spellicon441591|cFFFFFFFF$@spellname441591|r\n$@spelldesc441591]"
WoWFA_Data[441583] = "حمله‌های خودکار شما شانس دارند که $?a137010[Maul][Ferocious Bite] بعدی شما را به Ravage تبدیل کنند.\n\n$?a137010[|cFFFFFFFFRavage|r\nSlash through your target in a wide arc, dealing $s1 Physical damage to your target and $s2 to all other enemies in front of you.]$?a137011[|cFFFFFFFFRavage|r\nFinishing move that slashes through your target in a wide arc, dealing Physical damage per combo point to your target and consuming up to $?a102543[18.75][25] additional Energy to increase that damage by up to 100%. Hits all other enemies in front of you for reduced damage per combo point spent. \n\n1 point: ${$m1*1/5} damage, ${$m3*1/5} in an arc\n2 points: ${$m1*2/5} damage, ${$m3*2/5} in an arc\n3 points: ${$m1*3/5} damage, ${$m3*3/5} in an arc\n4 points: ${$m1*4/5} damage, ${$m3*4/5} in an arc\n5 points: ${$m1*5/5} damage, ${$m3*5/5} in an arc]"
WoWFA_Data[441675] = "حداکثر انرژی و خشم شما 20 افزایش می‌یابد.\n\nFrenzied Regeneration همچنین حداکثر سلامتی شما را 10% افزایش می‌دهد."
WoWFA_En[441678] = "Ironfur and Frenzied Regeneration persist in Cat Form.$?!c3[\n\nWhen transforming from Bear to Cat Form, you retain $441685s1% of your Bear Form armor and health for $441685d.][]\n\nFor $441686d after entering Bear Form, you heal for $441686s1% of damage taken over $441688d. "
WoWFA_Data[441678] = "Ironfur و Frenzied Regeneration در حالت Cat Form باقی می‌مانند.$?!c3[\n\nوقتی از Bear Form به Cat Form تغییر شکل می‌دهید، برای 6 ثانیه، 80% از زره و سلامتی Bear Form خود را حفظ می‌کنید.][]\n\nبرای 6 ثانیه پس از ورود به Bear Form، طی 8 ثانیه به‌اندازهٔ 10% از آسیب دریافتی شفا می‌گیرید."
WoWFA_En[441689] = "Frenzied Regeneration can be cast in Cat Form for $s2 Energy.\n\nBear Form reduces magic damage you take by ${-$s4}%.\n\nShred and $?s202028[Brutal Slash][Swipe] damage increased by $s5%. Mangle damage increased by $s6%."
WoWFA_Data[441689] = "Frenzied Regeneration در حالت Cat Form با 40 انرژی قابل کست است.\n\nBear Form آسیب جادویی دریافتی شما را 6% کاهش می‌دهد.\n\nآسیب Shred و $?s202028[Brutal Slash][Swipe] به‌اندازهٔ 10% افزایش می‌یابد. آسیب Mangle به‌اندازهٔ 25% افزایش می‌یابد."
WoWFA_En[441691] = "$?s202028[Shred and Brutal Slash]?a137011[Shred and Swipe][]$?a137011[ grant Ursine Potential. When you have $441695s1 stacks, the next time you transform into Bear Form, your next Mangle deals $441698s1% increased damage or your next Swipe deals $441698s2% increased damage. Either generates ${$442562s1/10} extra Rage.][Mangle grants Feline Potential. When you have $441701s1 stacks, the next time you transform into Cat Form, gain $441704s1 combo points and your next Ferocious Bite or Rip deals $441702s1% increased damage for its full duration.]"
WoWFA_Data[441691] = "$?s202028[Shred و Brutal Slash]?a137011[Shred و Swipe][]$?a137011[ اثر Ursine Potential می‌دهند. وقتی 8 استک داشته باشید، دفعهٔ بعد که به Bear Form تبدیل می‌شوید، Mangle بعدی شما 50% یا Swipe بعدی شما 50% آسیب بیشتری وارد می‌کند. هر کدام 15 خشم اضافی تولید می‌کند.][Mangle اثر Feline Potential می‌دهد. وقتی 6 استک داشته باشید، دفعهٔ بعد که به Cat Form تبدیل می‌شوید، 5 combo point می‌گیرید و Ferocious Bite یا Rip بعدی شما برای کل مدت خود، 50% آسیب بیشتری وارد می‌کند.]"
WoWFA_En[441809] = "Ravage also inflicts a Bleed that causes $?a137011[$441812s1][$451177s1] damage over $441812d and saps its victims' strength, reducing damage they deal to you by $?a137011[$441812s2][$451177s2]%.\n\nDreadful Wound is not affected by Circle of Life and Death. $?a137011[If a Dreadful Wound benefiting from Tiger's Fury is re-applied, the new Dreadful Wound deals damage as if Tiger's Fury was active.][]"
WoWFA_Data[441809] = "Ravage همچنین یک Bleed اعمال می‌کند که طی 6 ثانیه، $?a137011[$441812s1][$451177s1] آسیب وارد می‌کند و قربانیان را ضعیف می‌کند؛ آسیبی که به شما وارد می‌کنند $?a137011[4][15]% کاهش می‌یابد.\n\nDreadful Wound تحت تأثیر Circle of Life and Death قرار نمی‌گیرد. $?a137011[اگر Dreadful Woundی که از Tiger's Fury سود می‌برد دوباره اعمال شود، Dreadful Wound جدید طوری آسیب می‌دهد که انگار Tiger's Fury فعال است.][]"
WoWFA_Data[441814] = "Ravage برای 6 ثانیه، سرعت حملهٔ خودکار شما را به‌اندازهٔ 35% افزایش می‌دهد."
WoWFA_En[441824] = "Ravage increases your Agility by $441825s1% and the armor granted by Ironfur by $441825s2% for $441825d.\n\nYour first $?a137011[Tiger's Fury][Mangle] after entering combat makes your next $?a137011[Ferocious Bite][Maul] become Ravage."
WoWFA_Data[441824] = "Ravage برای 8 ثانیه، Agility شما را 8% و زرهٔ اعطایی Ironfur را 20% افزایش می‌دهد.\n\nاولین $?a137011[Tiger's Fury][Mangle] شما پس از ورود به نبرد، $?a137011[Ferocious Bite][Maul] بعدی شما را به Ravage تبدیل می‌کند."
WoWFA_En[441829] = "Every $?a137010[Maul, Raze, Mangle,  Thrash, or Swipe]$?a137011[attack with an Energy cost that] you cast extends the duration of your Dreadful Wounds by $?a137010[${$s1/1000}.1][${$s2/1000}.1] sec, up to $s3 additional sec."
WoWFA_Data[441829] = "هر $?a137010[Maul، Raze، Mangle،  Thrash یا Swipe]$?a137011[حملهٔ دارای هزینهٔ انرژی که] کست می‌کنید، مدت Dreadful Woundهای شما را $?a137010[0.6][0.6] ثانیه تمدید می‌کند؛ تا 8 ثانیه اضافی."
WoWFA_En[441835] = "During Berserk, $?c3[Mangle, Thrash][Shred], and $?s202028[Brutal Slash][Swipe] have a $s1% chance to make your next $?a137010[Maul][Ferocious Bite] become Ravage."
WoWFA_Data[441835] = "در طول Berserk، $?c3[Mangle و Thrash][Shred] و $?s202028[Brutal Slash][Swipe] 20% شانس دارند که $?a137010[Maul][Ferocious Bite] بعدی شما را به Ravage تبدیل کنند."
WoWFA_En[441841] = "$?a137011[Ferocious Bite and Rampant Ferocity damage increased by $s1% and Primal Wrath's direct damage increased by $s2%.][Maul and Raze damage increased by $s3%.]"
WoWFA_Data[441841] = "$?a137011[آسیب Ferocious Bite و Rampant Ferocity به‌اندازهٔ 10% و آسیب مستقیم Primal Wrath به‌اندازهٔ 60% افزایش می‌یابد.][آسیب Maul و Raze به‌اندازهٔ 10% افزایش می‌یابد.]"
WoWFA_Data[441844] = "مدت Stampeding Roar به‌اندازهٔ 25% افزایش می‌یابد."
WoWFA_En[441845] = "$?c2[Shred, Swipe, and Rake damage increased by $s1% and their critical strike chance is increased by $s3%.][Mangle damage increased by $s4% and its critical strike chance is increased by $s5%.]\n\n$?c3[Mangle heals you for $458724s1% of maximum health.][]"
WoWFA_Data[441845] = "$?c2[آسیب Shred، Swipe و Rake به‌اندازهٔ 10% و شانس Critical Strike آن‌ها به‌اندازهٔ 5% افزایش می‌یابد.][آسیب Mangle به‌اندازهٔ 10% و شانس Critical Strike آن به‌اندازهٔ 10% افزایش می‌یابد.]\n\n$?c3[Mangle به‌اندازهٔ 5% از حداکثر سلامتی به شما شفا می‌دهد.][]"
WoWFA_En[441846] = "$?c2[Damage dealt by Chomp and ][]$?(c2&!s1243807)[Feral Frenzy]?c2[Frantic Frenzy][]$?c2[ increased by $s2%][The cooldown of Sundering Roar is reduced by ${$s1/-1000} sec]."
WoWFA_Data[441846] = "$?c2[آسیب واردشده توسط Chomp و ][]$?(c2&!s1243807)[Feral Frenzy]?c2[Frantic Frenzy][]$?c2[ به‌اندازهٔ 25% افزایش می‌یابد][کول‌داون Sundering Roar به‌اندازهٔ 15 ثانیه کاهش می‌یابد]."
WoWFA_Data[443046] = "استفاده از Wild Charge در حالت Bear Form یا Moonkin Form، کول‌داونی 3 ثانیه کوتاه‌تر دارد."
WoWFA_Data[447131] = "Rejuvenation بلافاصله به‌اندازهٔ 20% از کل اثر دوره‌ای خود به هدف شما شفا می‌دهد و مدت Regrowth به‌اندازهٔ 3 ثانیه افزایش می‌یابد."
WoWFA_Data[449182] = "Stamina به‌اندازهٔ 4% افزایش می‌یابد.\n\nStamina در حالت Bear Form به‌اندازهٔ 5% دیگر نیز افزایش می‌یابد."
WoWFA_Data[449184] = "آسیب Ferocious Bite و Maul به‌اندازهٔ 8% افزایش می‌یابد."
WoWFA_Data[449185] = "آسیب Moonfire و Sunfire به‌اندازهٔ 10% افزایش می‌یابد."
WoWFA_Data[449191] = "Survival Instincts و Barkskin آسیب دریافتی را به‌اندازهٔ 10% دیگر کاهش می‌دهند."
WoWFA_Data[449193] = "Shred، Rake و Skull Bash در هر فرمی قابل استفاده هستند و در صورت لزوم شما را به حالت Cat Form می‌برند. \n\nMangle در هر فرمی قابل استفاده است و شما را به حالت Bear Form می‌برد. \n\nWrath و Starfire در صورت داشتن تلنت مربوط، شما را به حالت Moonkin Form می‌برند."
WoWFA_Data[449537] = "اگر combo point‌ای بیش از ظرفیت ذخیرهٔ خود تولید کنید، Ferocious Bite یا Primal Wrath بعدی شما 10% آسیب مستقیم بیشتری وارد می‌کند."
WoWFA_Data[449645] = "Tiger's Fury برای 8 ثانیه، Haste شما را به‌اندازهٔ 10% و نرخ بازیابی انرژی را به‌اندازهٔ 25% افزایش می‌دهد."
WoWFA_Data[450212] = "Starsurge برای 5 ثانیه، آسیبی که هدف از اثرات دوره‌ای و Shooting Stars شما دریافت می‌کند را به‌اندازهٔ 16% افزایش می‌دهد. اعمال دوبارهٔ این اثر مدت آن را تا سقف 20 ثانیه تمدید می‌کند. محدود به 1."
WoWFA_Data[450347] = "وقتی Eclipse تمام می‌شود یا وارد نبرد می‌شوید، وارد یک Dreamstate می‌شوید که زمان کست 2 Starfire یا Wrath بعدی شما را به‌اندازهٔ 30% کاهش می‌دهد."
WoWFA_Data[450356] = "کست کردن Wrath 12% شانس دارد که Starsurge یا Starfall بعدی شما را رایگان کند.\n\nکست کردن Starfire 15% شانس دارد که Starsurge یا Starfall بعدی شما را رایگان کند."
WoWFA_Data[450558] = "Starsurge یا Starfall بونوس آسیب Arcane یا Nature Eclipse فعلی شما را 2% دیگر افزایش می‌دهند؛ تا سقف 6%."
WoWFA_Data[450598] = "حداکثر Astral Power را 20 افزایش می‌دهد. ورود به Eclipse، هزینهٔ Astral Power اولین Starsurge یا Starfall بعدی شما را 15 کاهش می‌دهد."
WoWFA_En[451211] = "Wrath, Starsurge, and Starfire damage increased by $s1%. $?!a137013[\n\nStarsurge's cooldown is reduced by ${-$s2/1000} sec and its mana cost is reduced by $s3%.][]"
WoWFA_Data[451211] = "آسیب Wrath، Starsurge و Starfire به‌اندازهٔ 5% افزایش می‌یابد. $?!a137013[\n\nکول‌داون Starsurge به‌اندازهٔ 4 ثانیه و هزینهٔ Mana آن به‌اندازهٔ 50% کاهش می‌یابد.][]"
WoWFA_En[455461] = "When you remove an effect with Soothe or $?s88423[Nature's Cure][Remove Corruption], gain a combo point and heal for $s1% of your maximum health. If you are at full health an injured party or raid member will be healed instead."
WoWFA_Data[455461] = "وقتی با Soothe یا $?s88423[Nature's Cure][Remove Corruption] اثری را حذف می‌کنید، یک combo point می‌گیرید و به‌اندازهٔ 4% از حداکثر سلامتی خود شفا می‌گیرید. اگر سلامتی شما کامل باشد، به‌جای شما یک عضو پارتی یا ریدِ آسیب‌دیده شفا می‌گیرد."
WoWFA_En[455797] = "$?a137013[Entering Eclipse increases your haste by $455801s1% for $455801d][Swiftmend healing is increased by $s2%]."
WoWFA_Data[455797] = "$?a137013[ورود به Eclipse، Haste شما را برای 6 ثانیه به‌اندازهٔ 6% افزایش می‌دهد][شفای Swiftmend به‌اندازهٔ 20% افزایش می‌یابد]."
WoWFA_En[468743] = "$?s102560[Incarnation: Chosen of Elune][Celestial Alignment]'s cooldown is reduced by ${-$s3/1000} seconds and it has two charges."
WoWFA_Data[468743] = "کول‌داون $?s102560[اسپل Incarnation: Chosen of Elune][اسپل Celestial Alignment] به‌اندازهٔ 60 ثانیه کاهش می‌یابد و دو شارژ پیدا می‌کند."
WoWFA_En[468936] = "Sunfire damage has a chance to grow a magical mushroom at a target's location. After $468938d, the mushroom detonates, dealing $1280212s1 Nature damage and then an additional $1280213o1 Nature damage over $1280213d. Affected targets are slowed by ${$1280213s2*-1}%.\n\nGenerates up to $1280212s2 Astral Power based on targets hit."
WoWFA_Data[468936] = "آسیب Sunfire شانس دارد در مکانی یک قارچ جادویی برویاند. پس از 1 ثانیه، قارچ منفجر می‌شود، $1280212s1 آسیب Nature و سپس $1280213o1 آسیب Nature اضافی طی 10 ثانیه وارد می‌کند. اهداف تحت تأثیر به‌اندازهٔ 50% کند می‌شوند.\n\nبر اساس اهداف برخوردکرده، تا 20 Astral Power تولید می‌کند."
WoWFA_Data[469004] = "کست کردن Starsurge یا Starfall رایگان، به‌مدت 3 ثانیه Solstice اعطا می‌کند."
WoWFA_Data[470549] = "شفای Swiftmend به‌اندازهٔ 30% افزایش می‌یابد."
WoWFA_Data[470562] = "کول‌داون Swiftmend به‌اندازهٔ 15% کاهش می‌یابد؛ روی اهداف با سلامتی کمتر، تا 30% بیشتر."
WoWFA_Data[471492] = "کاهش آسیب جادویی برابر با 10% از کاهش آسیب زره شما به دست می‌آورید."
WoWFA_Data[474526] = "آسیب Rake، Rip و Thrash به‌اندازهٔ 10% افزایش می‌یابد."
WoWFA_En[474530] = "Physical damage dealt by your abilities increased by $?a137012[$s3][$s1]%."
WoWFA_Data[474530] = "آسیب Physical واردشده توسط توانایی‌های شما به‌اندازهٔ $?a137012[25][5]% افزایش می‌یابد."
WoWFA_En[474541] = "Magical damage dealt by your spells increased by $?a137012[$s3][$s1]%."
WoWFA_Data[474541] = "آسیب جادویی واردشده توسط اسپل‌های شما به‌اندازهٔ $?a137012[25][5]% افزایش می‌یابد."
WoWFA_Data[474678] = "وقتی حمله‌ای بیش از 12% از حداکثر سلامتی شما آسیب وارد کند، فوراً به‌اندازهٔ 10% از سلامتی خود شفا می‌گیرید.\n\nاین اثر نمی‌تواند بیشتر از یک بار در هر 30 ثانیه رخ دهد."
WoWFA_Data[474750] = "با یک متحد پیوند می‌بندید. شفای شخصی شما نیز متحد پیوندخوردهٔ شما را به‌میزان 10% از مقدار شفا شفا می‌دهد. شفای شما روی این متحد نیز شما را به‌میزان 8% از همان مقدار شفا می‌دهد."
WoWFA_Data[1213597] = "Well-Honed Instincts می‌تواند حداکثر یک بار در هر 90 ثانیه فعال شود."
WoWFA_Data[1217941] = "شفای Efflorescence به‌اندازهٔ 25% افزایش می‌یابد و اکنون به‌طور خودکار زیر پای هدف Lifebloom شما می‌روید."
WoWFA_En[1226140] = "Casting Swiftmend or Wild Growth summons a Treant that casts Nourish on that target or a nearby ally periodically, healing for ${$422090m1}. Lasts $102693d."
WoWFA_Data[1226140] = "کست کردن Swiftmend یا Wild Growth، یک Treant احضار می‌کند که به‌صورت دوره‌ای روی آن هدف یا متحدی نزدیک Nourish کست می‌کند و ${$422090m1} شفا می‌دهد. 8 ثانیه دوام دارد."
WoWFA_Data[1232897] = "در هر فرم، بونوسی الهام‌گرفته از گسترهٔ دانش دروئیدی خود می‌گیرید:\n\nبدون فرم: 4% آسیب جادویی\nCat Form: 4% Stamina\nBear Form: 5% سرعت حرکت\nMoonkin Form: 3% کاهش آسیب منطقه‌ای دریافتی"
WoWFA_En[1239669] = "You may draw the sun and moon into alignment for $48517d, empowering either your Nature or Arcane spells. Casting Wrath or Starfire changes what mode of Eclipse will be entered, and the two modes of Eclipse share a button and $?a1240188[${$s1+$1240188s1/1000}][$s1] sec cooldown.\n\n$@spellicon48517 $@spellname48517\nNature spells deal $48517s1% additional damage and Wrath damage is increased by $48517s3%.\n\n$@spellicon48518 $@spellname48518\nArcane spells deal $48518s1% additional damage and Starfire damage is increased by $48518s3%."
WoWFA_Data[1239669] = "می‌توانید برای 15 ثانیه خورشید و ماه را همسو کنید و اسپل‌های Nature یا Arcane خود را تقویت کنید. کست کردن Wrath یا Starfire مشخص می‌کند کدام حالت Eclipse وارد شود، و دو حالت Eclipse یک دکمه و کول‌داون $?a1240188[29][32] ثانیه‌ای مشترک دارند.\n\n Eclipse (Solar)\nاسپل‌های Nature 15% آسیب اضافی وارد می‌کنند و آسیب Wrath به‌اندازهٔ 40% افزایش می‌یابد.\n\n Eclipse (Lunar)\nاسپل‌های Arcane 15% آسیب اضافی وارد می‌کنند و آسیب Starfire به‌اندازهٔ 40% افزایش می‌یابد."
WoWFA_Data[1240185] = "آسیب Moonfire، Sunfire و Shooting Stars به‌اندازهٔ 10% افزایش می‌یابد."
WoWFA_Data[1240188] = "کول‌داون Eclipse قمری و Eclipse خورشیدی به‌اندازهٔ 3 ثانیه کاهش می‌یابد."
WoWFA_Data[1240206] = "ورود به هر Eclipse، 15% شانس دارد مزایای هر دو Eclipse قمری و خورشیدی را اعطا کند."
WoWFA_Data[1240262] = "Starfall آسیب خود را 100% سریع‌تر وارد می‌کند."
WoWFA_Data[1240283] = "وقتی با کمتر از 40 Astral Power از Eclipse خارج می‌شوید، زمان کست Wrath و Starfire برای 15 ثانیه یا تا ورود به Eclipse بعدی، به‌اندازهٔ 20% کاهش می‌یابد."
WoWFA_Data[1240906] = "Eclipse قمری و Eclipse خورشیدی یک شارژ اضافی دارند."
WoWFA_En[1240907] = "Every time Starfall drops a wave of stars, a meteorite also falls on up to $s1 targets in its range, each dealing $1240913s1 Astral damage."
WoWFA_Data[1240907] = "هر بار که Starfall موجی از ستاره‌ها می‌ریزد، یک سنگ آسمانی نیز بر تا 2 هدف در برد آن فرود می‌آید و هر کدام $1240913s1 آسیب Astral وارد می‌کنند."
WoWFA_En[1243807] = "Unleash a furious frenzy, flickering to nearby targets in front of you $s1 times and clawing all enemies around them for $1244079s1 Physical damage and an additional ${$1244079s3*$1244079d/$1244079t3} Bleed damage over $1244079d.\n\n|cFFFFFFFFAwards $s1 combo points.|r"
WoWFA_Data[1243807] = "خشمی دیوانه‌وار آزاد می‌کنید؛ 5 بار به اهداف نزدیک جلوی شما جهش کرده و به تمام دشمنان اطراف آن‌ها $1244079s1 آسیب Physical و ${$1244079s3*$1244079d/$1244079t3} آسیب Bleed اضافی طی 6 ثانیه وارد می‌کنید.\n\n|cFFFFFFFF5 combo point اعطا می‌کند.|r"
WoWFA_En[1244258] = "Chomp your target, causing $s1 Physical damage. Chomp critical strikes deal ${$1244292s3/100+2} times normal damage.\n\nChomp can only be used when you fall below ${$1244292s1+1}% Energy or for ${$1244393s1/1000} seconds afterward."
WoWFA_Data[1244258] = "هدف را گاز می‌گیرید و $s1 آسیب Physical وارد می‌کنید. Critical Strikeهای Chomp، 3 برابر آسیب عادی وارد می‌کنند.\n\nChomp فقط زمانی قابل استفاده است که انرژی شما زیر 30% برود، یا برای 2 ثانیه پس از آن."
WoWFA_Data[1244331] = "24% از شکوفهٔ نهایی Lifebloom، تا 5 متحد آسیب‌دیده در فاصلهٔ 40 یاردی را شفا می‌دهد."
WoWFA_Data[1244470] = "وقتی Swiftmend کست می‌کنید، Lifebloom به یک Blooming Frenzy تبدیل می‌شود و باعث می‌شود 3 بار پشت‌سرهم سریع بشکفد."
WoWFA_Data[1244532] = "آسیب Ferocious Bite به هدف اصلی‌اش، به‌ازای هر دشمنِ تحت Rip شما، به‌اندازهٔ 8% افزایش می‌یابد؛ تا سقف 6."
WoWFA_Data[1244544] = "کول‌داون Feral Frenzy به‌اندازهٔ 15 ثانیه کاهش می‌یابد و آسیب آن به‌اندازهٔ 15% افزایش می‌یابد."
WoWFA_Data[1244547] = "وقتی دشمنی تحت Rip شما می‌میرد، 10 انرژی می‌گیرید و آسیب واردشدهٔ شما برای 8 ثانیه به‌اندازهٔ 5% افزایش می‌یابد؛ تا 5 بار استک می‌شود."
WoWFA_Data[1244632] = "آسیب اثرات Bleed شما به‌اندازهٔ 10% افزایش می‌یابد."
WoWFA_Data[1250906] = "هر بار که خشم مصرف می‌کنید شفا می‌گیرید؛ به‌ازای 80 خشم مصرف‌شده، تا 0.8% از حداکثر سلامتی شما."
WoWFA_Data[1250923] = "Barkskin حداکثر سلامتی شما را 20% افزایش می‌دهد، اما مدت آن 40% کاهش می‌یابد."
WoWFA_Data[1251406] = "وقتی از حالت Bear Form خارج می‌شوید، مزایای آن به سلامتی و زره طی 8 ثانیه به‌تدریج محو می‌شود."
WoWFA_Data[1251876] = "Ironfur increases your Mastery by 5%."
WoWFA_En[1252871] = "Channel the power of the enraged moon to deal $o1 Arcane damage to your target over $d. Casting Mangle extends its duration by ${$s2/1000}.1 sec and generates ${$1253582s1/10} Rage."
WoWFA_Data[1252871] = "قدرت ماه خشمگین را کانال می‌کنید تا طی 8 ثانیه، $o1 آسیب Arcane به هدف شما وارد کند. کست کردن Mangle مدت آن را 1 ثانیه تمدید کرده و 8 خشم تولید می‌کند."
WoWFA_Data[1252994] = "Maul و Raze می‌توانند تا 20 خشم بیشتر مصرف کنند و تا 70% آسیب اضافی وارد کنند."
WoWFA_Data[1253035] = "Mangle 1 شارژ اضافی دارد و وقتی Maul با 80 خشم یا بیشتر کست شود، شانس فعال‌سازی Gore آن به‌اندازهٔ 100% افزایش می‌یابد."
WoWFA_En[1253461] = "Awaken memories of past conflicts, causing a Dread Shade to take form nearby.\n\nWhile active, shades slowly travel toward your target, dealing $1253488s1 Nature damage to nearby enemies and mirroring your Thrash casts."
WoWFA_Data[1253461] = "خاطرات نبردهای گذشته را بیدار می‌کنید و باعث می‌شوید یک Dread Shade در نزدیکی شکل بگیرد.\n\nدر طول فعال‌بودن، سایه‌ها به‌آرامی به سمت هدف شما حرکت می‌کنند، به دشمنان نزدیک $1253488s1 آسیب Nature وارد می‌کنند و کست‌های Thrash شما را آینه‌وار تکرار می‌کنند."
WoWFA_En[1253799] = "Roar with earthshattering ferocity, dealing $s2 Physical damage, and resetting the cooldown of Thrash and allowing it to stack $s1 additional times for $d. \n\nWhen Sundering Roar ends, any excess stacks of Thrash immediately deal their remaining damage."
WoWFA_Data[1253799] = "با خشمی زمین‌لرزان غرش می‌کنید، $s2 آسیب Physical وارد می‌کنید، کول‌داون Thrash را ریست می‌کنید و برای 12 ثانیه اجازه می‌دهید 5 بار دیگر استک شود. \n\nوقتی Sundering Roar تمام می‌شود، استک‌های اضافی Thrash بلافاصله آسیب باقی‌ماندهٔ خود را وارد می‌کنند."
WoWFA_Data[1261564] = "فعال‌کردن یک Eclipse، Wrath یا Starfire بعدی شما را کست فوری می‌کند. 3 Starsurge یا Starfall اولی که در هر Eclipse کست می‌کنید، 20% آسیب بیشتری وارد می‌کنند."
WoWFA_Data[1261565] = "هر Critical Strike شما در طول Eclipse، هدف را وادار می‌کند طی 8 ثانیه، 10% اضافی از آسیب واردشده را به‌صورت آسیب در طول زمان دریافت کند."
WoWFA_En[1261566] = "Activating an Eclipse also launches Solar or Lunar Bolts at enemies within $s1 yds that always critically strike.\n\n$@spellicon1261573 $@spellname1261573\nEntering Solar Eclipse launches a Solar Bolt at $s2 $Lenemy:enemies; that deals $1261573s1 Nature damage.\n\n$@spellicon1263137 $@spellname1263137\nEntering Lunar Eclipse launches $s3 Lunar Bolts at enemies that deal $1263137s1 Arcane damage to them and nearby targets. Deals reduced damage beyond 5 targets.\n"
WoWFA_Data[1261566] = "فعال‌کردن یک Eclipse همچنین Solar یا Lunar Boltهایی به سمت دشمنان در فاصلهٔ 40 یاردی شلیک می‌کند که همیشه Critical Strike می‌خورند.\n\n Solar Bolt\nورود به Eclipse خورشیدی، یک Solar Bolt به سمت 1 دشمن شلیک می‌کند که $1261573s1 آسیب Nature وارد می‌کند.\n\n Lunar Bolt\nورود به Eclipse قمری، 3 Lunar Bolt به سمت دشمنان شلیک می‌کند که به آن‌ها و اهداف نزدیک $1263137s1 آسیب Arcane وارد می‌کند. آسیب پس از 5 هدف کاهش می‌یابد."
WoWFA_En[1261867] = "Perform a powerful off-role ability depending on your currently active shapeshift form.$?c4[][\n\n|cFFFFFFFFNon-shapeshifted:|r\nEmpowered Wild Growth that heals up to $48438s2 injured allies within $48438A1 yards of the target for ${$48438o1*$s4/100} over $48438d.]$?c1[]?c2[][\n\n|cFFFFFFFFCat Form:|r\nUnleash an empowered Feral Frenzy, clawing your target $274837m2 times for ${$274837m2*$274838s1*$s2/100} Physical damage and an additional ${$274837m2*$s2/100*$274838s3*$274838d/$274838t3} Bleed damage over $274838d. Awards 5 combo points.\n\n|cFFFFFFFFMoonkin Form:|r\nCall down waves of empowered falling stars upon enemies within $50286A1 yds, dealing ${54*$191037s1} Astral damage over $191034d.]$?c3[][\n\n|cFFFFFFFFBear Form:|r\nIncrease your maximum health by $1261872s1% for $1261872d.]"
WoWFA_Data[1261867] = "بسته به حالت تغییر شکل فعلی شما، یک توانایی قدرتمند خارج از نقش اصلی اجرا می‌کند.$?c4[][\n\n|cFFFFFFFFبدون تغییر شکل:|r\nیک Wild Growth تقویت‌شده که تا 5 متحد آسیب‌دیده در فاصلهٔ 30 یاردیِ هدف را طی 7 ثانیه به‌اندازهٔ ${$48438o1*$s4/100} شفا می‌دهد.]$?c1[]?c2[][\n\n|cFFFFFFFFCat Form:|r\nیک Feral Frenzy تقویت‌شده آزاد می‌کنید؛ 5 بار چنگ به هدف می‌زنید و ${$274837m2*$274838s1*$s2/100} آسیب Physical و ${$274837m2*$s2/100*$274838s3*$274838d/$274838t3} آسیب Bleed اضافی طی 6 ثانیه وارد می‌کنید. 5 combo point اعطا می‌کند.\n\n|cFFFFFFFFMoonkin Form:|r\nموج‌هایی از ستاره‌های در حال سقوطِ تقویت‌شده را بر دشمنان در فاصلهٔ 40 یاردی فرومی‌بارید و طی 8 ثانیه، ${54*$191037s1} آسیب Astral وارد می‌کنید.]$?c3[][\n\n|cFFFFFFFFBear Form:|r\nطی 20 ثانیه، حداکثر سلامتی شما به‌اندازهٔ 30% افزایش می‌یابد.]"
WoWFA_Data[1262034] = "Mark of the Wild روی خودتان 100% مؤثرتر است."
WoWFA_En[1263657] = "When you Ferocious Bite, you have a $s1% chance per combo point spent to flicker to an enemy within $s2 yds and deliver an Unseen Attack. Unseen Attack damage is reduced if less than 5 combo points and ${$22568c+$22568s2} Energy are spent on Ferocious Bite.\n\n$@spellicon1263827 $@spellname1263827\n$@spelldesc1263827\n\n$@spellicon1263902 $@spellname1263902\n$@spelldesc1263902\n\n\n"
WoWFA_Data[1263657] = "وقتی Ferocious Bite می‌زنید، به‌ازای هر combo point مصرف‌شده 15% شانس دارید به دشمنی در فاصلهٔ 30 یاردی جهش کنید و یک Unseen Attack وارد کنید. اگر کمتر از 5 combo point و ${$22568c+$22568s2} انرژی روی Ferocious Bite مصرف شود، آسیب Unseen Attack کاهش می‌یابد.\n\n Unseen Slash\nSlash the target, dealing $1263890s1 Physical damage and an additional ${$1271863s2*$1271863d/$1271863t2} Bleed damage over 6 ثانیه. If this effect is reapplied, any remaining damage is added to the new Bleed.\n\n Unseen Swipe\nSwipe nearby targets, dealing $1263908s1 Physical damage. Damage reduced beyond 5 targets."
WoWFA_En[1263658] = "Unseen Attacks increase your damage done by $s1% for $1263939d per combo point spend to trigger it. Additional applications extend this effect."
WoWFA_Data[1263658] = "Unseen Attackها به‌ازای هر combo point صرف‌شده برای فعال‌سازی‌شان، آسیب شما را برای 1 ثانیه به‌اندازهٔ $s1% افزایش می‌دهند. اعمال‌های بعدی این اثر را تمدید می‌کنند."
WoWFA_Data[1263660] = "Tiger's Fury باعث می‌شود پس از 2 حملهٔ تولید combo point بعدی خود، یک Unseen Attack با حداکثر آسیب انجام دهید. آسیب Rip و Unseen Attack به‌اندازهٔ 30% افزایش می‌یابد."
WoWFA_Data[1263879] = "Regrowth به‌ازای 15% از شفای خود، تا 3 متحد دارای Rejuvenation فعال را شفا می‌دهد و به متحدانی با کمترین سلامتی اولویت می‌دهد."
WoWFA_En[1264614] = "$?c1[Entering an Eclipse summons a Dryad to assist you for $1264618d, casting Starsurge dealing $1264677s1 Astral damage and Starfall at $s2% effectiveness.][Your periodic heals have a chance to empower your next Swiftmend to summon a Dryad to assist you, casting Tranquility at $s1% effectiveness and Regrowth to heal $1264664s1 damage onto your lowest health ally.]"
WoWFA_Data[1264614] = "$?c1[ورود به یک Eclipse، برای 8 ثانیه یک Dryad فرامی‌خواند که به شما کمک می‌کند و Starsurge با $1264677s1 آسیب Astral و Starfall با اثربخشی 250% کست می‌کند.][شفاهای دوره‌ای شما شانس دارند Swiftmend بعدی شما را تقویت کنند تا یک Dryad احضار شود که با اثربخشی 10% Tranquility و Regrowth کست می‌کند و $1264664s1 به متحدی با کمترین سلامتی شفا می‌دهد.]"
WoWFA_Data[1264649] = "وقتی Regrowth شفای Critical Strike می‌دهد، به‌جای 200% عادی، 260% اثربخشی دارد."
WoWFA_En[1264776] = "$?c4[Dryads cause Swiftmend to cool down $1264618s3% faster.][Dryads cause most of your Astral power generation to be increased by $1264618s4%.]"
WoWFA_Data[1264776] = "$?c4[Dryadها باعث می‌شوند کول‌داون Swiftmend با سرعت 25% بیشتری کم شود.][Dryadها باعث می‌شوند بیشتر تولید Astral Power شما 10% افزایش یابد.]"
WoWFA_En[1264899] = "$?c4[Ironbark summons a Dryad to channel a beam of pure nature onto your target, healing them for $1264905o1 over $1264905d.][Your Starfall damage is increased by $s1% and your Starsurge damage is increased by $s2%.]"
WoWFA_Data[1264899] = "$?c4[Ironbark یک Dryad احضار می‌کند که پرتوهایی از نیروی خالص طبیعت را روی هدف شما کانال می‌کند و طی 6 ثانیه به‌اندازهٔ $1264905o1 به او شفا می‌دهد.][آسیب Starfall شما 18% و آسیب Starsurge شما 8% افزایش می‌یابد.]"
WoWFA_En[1269614] = "Spending Rage has a $s2% chance to awaken a guardian spirit for $1308647d, which attacks a nearby enemy for $1308093s1 when you cast Thrash or Mangle."
WoWFA_Data[1269614] = "مصرف خشم، 10% شانس دارد که برای 8 ثانیه روحی نگهبان را بیدار کند که هر بار شما Thrash یا Mangle کست می‌کنید، به دشمنی نزدیک $1308093s1 حمله می‌کند."
WoWFA_En[1269617] = "Mangle, $?s400254[Raze][Maul] and Ravage deal $s2% additional Nature damage over $1270065d. Your Mastery is increased by $s1%."
WoWFA_Data[1269617] = "Mangle، $?s400254[Raze][Maul] و Ravage طی 12 ثانیه، 20% آسیب Nature اضافی وارد می‌کنند. Mastery شما به‌اندازهٔ 3% افزایش می‌یابد."
WoWFA_En[1269619] = "When a spirit is awakened, the cooldowns of Thrash and Mangle are reset, and they deal $1308647s1% increased damage while the spirit is with you. Each time a spirit attacks, you generate ${$1308125s1/10} additional Rage.\n\nAfter casting $?s102558[Incarnation: Guardian of Ursoc][Berserk], gain $s1 $Lcharge:charges; of Wild Guardian:\n\n$@spellicon1269658 $@spellname1269658:\n$@spelldesc1269658"
WoWFA_Data[1269619] = "وقتی روحی بیدار می‌شود، کول‌داون Thrash و Mangle ریست می‌شود و تا زمانی که روح همراه شماست، این دو 30% آسیب بیشتری وارد می‌کنند. هر بار که روح حمله می‌کند، 8 خشم اضافی تولید می‌کنید.\n\nپس از کست کردن $?s102558[Incarnation: Guardian of Ursoc][Berserk]، 1 شارژ Wild Guardian می‌گیرید:\n\n Wild Guardian:\nYour next cast of $?s400254][Raze][Maul] or Ravage is guaranteed to awaken a spirit."
WoWFA_En[1270565] = "The rate at which $?c2[Bloodseeker Vines][Symbiotic Blooms] grow is increased by $?c2[$s1][$s2]%."
WoWFA_Data[1270565] = "نرخ روییدن $?c2[Bloodseeker Vineها][Symbiotic Bloomها] به‌اندازهٔ $?c2[20][20]% افزایش می‌یابد."
WoWFA_En[1270586] = "$?c2[Bloodseeker Vines][Symbiotic Blooms] have a $?c2[$s1][$s2]% chance to trigger Bursting Growth every 2 sec at $?c2[$s3][$s4]% effectiveness.\n"
WoWFA_Data[1270586] = "$?c2[Bloodseeker Vineها][Symbiotic Bloomها] $?c2[30][20]% شانس دارند هر 2 ثانیه با اثربخشی $?c2[100][100]% یک Bursting Growth فعال کنند."
WoWFA_En[1270592] = "Your $?c2[Bleeds and other damage over time][heal over time] effects are $?c2[$s1][$s3]% more effective."
WoWFA_Data[1270592] = "اثرات $?c2[Bleed و آسیب در طول زمان دیگر][شفای در طول زمان] شما $?c2[10][6]% اثربخش‌ترند."
WoWFA_En[1271206] = "$?c1[Gaining Astral Power with Starfire][Thrash] has a $?c1[$s1][$s2]% chance to launch a Starsurge at a victim at $?c1[$s3][$s4]% effectiveness.\n"
WoWFA_Data[1271206] = "$?c1[گرفتن Astral Power با Starfire][Thrash] $?c1[30][50]% شانس دارد که یک Starsurge با اثربخشی $?c1[50][120]% به سمت قربانی شلیک کند."
WoWFA_En[1271261] = "$?c1[Lunar Eclipse increases Arcane damage by an additional $s1%][\nLunar Beam increases Arcane damage you deal by $204066s6% while it is active]."
WoWFA_Data[1271261] = "$?c1[Eclipse قمری آسیب Arcane را 3% دیگر افزایش می‌دهد][\nLunar Beam در طول فعال‌بودن، آسیب Arcane واردشدهٔ شما را 10% افزایش می‌دهد]."
WoWFA_En[1271305] = "$?c1[Starsurge damage increased by $s1%. \nStarfall damage increased by $s2%.]?s400254[Raze][Maul] $?c3[damage increased by $s3%. Lunar Beam's damage dealt to its primary target increased by $s4%.][]\n"
WoWFA_Data[1271305] = "$?c1[آسیب Starsurge 5% افزایش می‌یابد. \nآسیب Starfall 10% افزایش می‌یابد.]?s400254[Raze][Maul] $?c3[آسیب آن 10% افزایش می‌یابد. آسیب Lunar Beam به هدف اصلی‌اش 30% افزایش می‌یابد.][]"
WoWFA_En[1271540] = "Your auto-attacks are 30% more likely to make your next $?c2[Ferocious Bite]?s400254[Raze][Maul] become Ravage."
WoWFA_Data[1271540] = "حمله‌های خودکار شما 30% شانس بیشتری دارند که $?c2[Ferocious Bite]?s400254[Raze][Maul] بعدی شما را به Ravage تبدیل کنند."
WoWFA_En[1271635] = "You have a $?c2[$s1][$s2]% chance to follow up any single target melee ability$?c3[ or Raze][] with a Twin Claw, dealing $?c2[$1271636s1][$1271657s1] Physical damage and generating $?c2[$1271636s2 Energy][${$1271657s2/10} Rage].\n\n"
WoWFA_Data[1271635] = "شما $?c2[16][18]% شانس دارید که پس از هر توانایی نزدیک تک‌هدف$?c3[ یا Raze][]، یک Twin Claw بزنید و $?c2[$1271636s1][$1271657s1] آسیب Physical وارد کرده و $?c2[3 انرژی][5 خشم] تولید کنید."
WoWFA_En[1271839] = "Your Dreadful Wounds increase the damage afflicted enemies take from your Bleed damage over time effects by $?c2[$s2][$s3]%."
WoWFA_Data[1271839] = "Dreadful Woundهای شما، آسیبی که دشمنانِ تحت اثر از اثرات آسیب در طول زمان Bleed شما دریافت می‌کنند را $?c2[8][15]% افزایش می‌دهند."
WoWFA_Data[1278789] = "وقتی Frenzied Regeneration بخواهد بیشتر از حداکثر سلامتی به شما شفا بدهد، 80% از شفای اضافی آن به‌جای آن به یک سپر جذب آسیب تبدیل می‌شود."
WoWFA_Data[1278886] = "وقتی آسیب غیردوره‌ای دریافت می‌کنید، شانس دارید یک شارژ Dream Guide بگیرید. \n\nوقتی شما یا متحدی نزدیک زیر 40% سلامتی برود، یک شارژ Dream Guide مصرف می‌کنید تا به‌طور خودکار روی او Regrowth کست کنید. این Regrowth، 100% شفای بیشتری می‌دهد."
WoWFA_Data[1280316] = "وقتی Shred یا Moonfire در شرف تولید combo point هستند، 25% شانس دارند به‌جای آن، combo point کامل تولید کنند."
